ALTER TABLE public.offerings ADD COLUMN routine_review_changed_by uuid;
CREATE OR REPLACE FUNCTION public.is_live_fund_reviewer(_user uuid, _fund uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.fund_team_grants g WHERE g.grantee_user_id=_user AND g.offering_id=_fund AND g.scope='fund' AND g.role::text='fund_reviewer' AND g.status='active' AND (g.expires_at IS NULL OR g.expires_at>now()) AND (EXISTS (SELECT 1 FROM public.fund_managers m WHERE m.offering_id=_fund AND m.user_id=g.granted_by) OR EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=g.granted_by AND r.role::text IN ('admin','super_admin')))); $$;
REVOKE ALL ON FUNCTION public.is_live_fund_reviewer(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_live_fund_reviewer(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.audit_routine_review_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.routine_review_user_id IS DISTINCT FROM OLD.routine_review_user_id THEN IF NEW.routine_review_changed_by IS NULL THEN RAISE EXCEPTION 'Recorded manager required'; END IF; IF NOT EXISTS (SELECT 1 FROM public.fund_managers WHERE offering_id=NEW.id AND user_id=NEW.routine_review_changed_by) AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=NEW.routine_review_changed_by AND role::text IN ('admin','super_admin')) THEN RAISE EXCEPTION 'Only manager or authorized administrator selects review owner'; END IF; IF NEW.routine_review_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fund_managers WHERE offering_id=NEW.id AND user_id=NEW.routine_review_user_id) AND NOT public.is_live_fund_reviewer(NEW.routine_review_user_id,NEW.id) THEN RAISE EXCEPTION 'Review owner must be manager or live exact-fund reviewer'; END IF; INSERT INTO public.fund_setup_events(subject_table,subject_id,event,detail,actor_user_id) VALUES ('offerings',NEW.id,'routine_review_owner_changed',jsonb_build_object('previous',OLD.routine_review_user_id,'next',NEW.routine_review_user_id),NEW.routine_review_changed_by); END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_routine_review_owner BEFORE UPDATE OF routine_review_user_id ON public.offerings FOR EACH ROW EXECUTE FUNCTION public.audit_routine_review_owner();
CREATE OR REPLACE FUNCTION public.guard_self_serve_document_review() RETURNS trigger LANGUAGE plpgsql SET search_path TO public AS $$ DECLARE current_v integer; BEGIN
 IF TG_OP = 'INSERT' THEN
  IF EXISTS (SELECT 1 FROM public.offering_document_versions WHERE offering_document_id = NEW.offering_document_id AND self_serve_review_state IS NOT NULL) THEN NEW.self_serve_review_state := 'pending'; END IF;
  IF NEW.self_serve_review_state IS NOT NULL AND (NEW.self_serve_review_state <> 'pending' OR NEW.approval_status <> 'uploaded_review_required') THEN RAISE EXCEPTION 'Generated drafts require review'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.self_serve_review_state IS NULL THEN RETURN NEW; END IF;
 IF NEW.self_serve_review_state IS NULL OR NEW.file_path IS DISTINCT FROM OLD.file_path OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.version IS DISTINCT FROM OLD.version OR NEW.offering_id IS DISTINCT FROM OLD.offering_id OR NEW.offering_document_id IS DISTINCT FROM OLD.offering_document_id OR NEW.generation_issues IS DISTINCT FROM OLD.generation_issues THEN RAISE EXCEPTION 'Generated version facts are immutable'; END IF;
 IF NEW.self_serve_review_state IS DISTINCT FROM OLD.self_serve_review_state THEN
  IF OLD.self_serve_review_state <> 'pending' OR NEW.self_serve_review_state NOT IN ('approved','returned') THEN RAISE EXCEPTION 'Review is already recorded'; END IF;
  IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN RAISE EXCEPTION 'Recorded reviewer is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fund_managers WHERE offering_id = OLD.offering_id AND user_id = NEW.approved_by) AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = NEW.approved_by AND role::text IN ('admin','super_admin','operations','fund_administration','legal','compliance')) AND NOT public.is_live_fund_reviewer(NEW.approved_by, OLD.offering_id) THEN RAISE EXCEPTION 'Reviewer must manage this fund or hold exact-fund review authority'; END IF;
  SELECT current_version INTO current_v FROM public.offering_documents WHERE id = OLD.offering_document_id;
  IF current_v IS DISTINCT FROM OLD.version THEN RAISE EXCEPTION 'Review the current version'; END IF;
  IF NEW.self_serve_review_state = 'approved' AND (NEW.approval_status <> 'approved' OR jsonb_array_length(OLD.generation_issues) > 0) THEN RAISE EXCEPTION 'Resolve document issues before approval'; END IF;
  IF NEW.self_serve_review_state = 'returned' AND coalesce(trim(NEW.self_serve_review_note),'') = '' THEN RAISE EXCEPTION 'Give a reason for returning the draft'; END IF;
 ELSIF OLD.self_serve_review_state IN ('approved','returned') AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.self_serve_review_note IS DISTINCT FROM OLD.self_serve_review_note OR NEW.signing_config IS DISTINCT FROM OLD.signing_config) THEN RAISE EXCEPTION 'Reviewed versions are frozen; create a new version'; END IF;
 IF NEW.approval_status = 'approved' AND NEW.self_serve_review_state <> 'approved' THEN RAISE EXCEPTION 'Complete draft review first'; END IF; RETURN NEW; END; $$;